#compliance-container {
  font-family: "Inter", "Segoe UI", Arial, sans-serif;
  width: 100%;
  color: #1e293b;
  background: #ffffff;
}

#compliance-title {
  margin-bottom: 2px;
  line-height: 1.2;
}

.compliance-header {
  min-width: 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  margin-bottom: 18px;
}

.compliance-badge {
  display: none;
  align-items: center;
  justify-content: center;
  padding: 6px 14px;
  border-radius: 0;
  font-size: 11px;
  font-weight: 600;
  white-space: nowrap;
  flex-shrink: 0;
  min-height: 30px;
}

.compliance-subtitle {
  font-size: 11px;
  color: #808080;
  font-weight: normal;
  margin-top: 0;
  margin-bottom: 18px;
  line-height: 1.3;
}

#compliance-container h3 {
  font-size: 17px;
  font-weight: 600;
  margin: 0 0 16px;
  color: #0f172a;
}

.table-wrapper {
  margin-top: 0;
  width: 100%;
  overflow-x: auto;
  border: 1px solid #cbd5e1;
  border-radius: 8px;
  background: #ffffff;
}

#compliance-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
  background: #ffffff;
}

/* Table headings */
#compliance-table thead th {
  background: #f1f5f9;
  color: #334155;
  text-align: left;
  padding: 14px 16px;
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.35px;
  border: 1px solid #cbd5e1;
  white-space: nowrap;
}

/* Table cells */
#compliance-table tbody td {
  padding: 14px 16px;
  border: 1px solid #e2e8f0;
  color: #334155;
  vertical-align: middle;
  line-height: 1.5;
}

/* Subtle row hover */
#compliance-table tbody tr:hover {
  background: #f8fafc;
}

/* Sortable headings */
.sort-button {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  border: none;
  background: transparent;
  color: inherit;
  font-family: inherit;
  font-size: inherit;
  font-weight: inherit;
  letter-spacing: inherit;
  cursor: pointer;
  text-align: left;
  padding: 0;
  width: 100%;
}

.sort-button:hover {
  color: #2563eb;
}

.sort-button:focus-visible {
  outline: 2px solid #2563eb;
  outline-offset: 3px;
}

/* Rating */
#compliance-table tbody td:nth-child(2) {
  font-weight: 600;
  color: #0f172a;
  white-space: nowrap;
}

/* Documents Found: clickable link style */
#compliance-table tbody td.documents-cell {
  color: #2563eb;
  font-weight: 500;
  cursor: pointer;
  min-width: 180px;
}

#compliance-table tbody td.documents-cell:hover {
  color: #1d4ed8;
  text-decoration: underline;
  background: #eff6ff;
}

#compliance-table tbody td.documents-cell:focus-visible {
  outline: 2px solid #2563eb;
  outline-offset: -3px;
}

/* TQ Query Status: bold green */
#compliance-table tbody td:last-child {
  color: #047857;
  font-weight: 700;
  white-space: nowrap;
}

/* Empty state */
.empty-message {
  text-align: center;
  padding: 24px !important;
  color: #64748b !important;
}

/* Responsive layout */
@media (max-width: 768px) {
  #compliance-table {
    min-width: 750px;
  }
  #compliance-table thead th,
  #compliance-table tbody td {
    padding: 11px 12px;
  }
}

