let sortColumn = "";
let sortDirection = "asc";
const columns = [{
  key: "categoryName",
  label: "Category Name",
  numeric: false
}, {
  key: "rating",
  label: "Rating",
  numeric: true
}, {
  key: "documentsFound",
  label: "Documents Found",
  numeric: false
}, {
  key: "documentsMissing",
  label: "Documents Missing",
  numeric: false
}, {
  key: "tqQueryStatus",
  label: "TQ Query Status",
  numeric: false
}];
function escapeHTML(value) {
  return String(value ?? "").replace(/[&<>"']/g, char => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#39;"
  })[char]);
}
function renderComplianceTable() {
  const title = document.getElementById("compliance-title");
  const subtitle = document.getElementById("compliance-subtitle");
  const badgeElement = document.getElementById("compliance-badge");
  const table = document.getElementById("compliance-table");
  const tbody = document.getElementById("compliance-body");
  if (!title || !table || !tbody) return;
  const model = appsmith.model || {};
  const rows = Array.isArray(model.rows) ? [...model.rows] : [];

  // Render title
  title.textContent = model.title || "Document Compliance — " + (model.selectedSupplierName || "Unknown Supplier");

  // Render subtitle
  if (subtitle) {
    subtitle.textContent = model.subtitle || "Specification and quality criteria review";
  }

  // Render supplier compliance badge
  if (badgeElement) {
    const badgeValue = model.complianceBadge;

    // Support either a text value or an object returned by the controller
    const badgeText = typeof badgeValue === "object" && badgeValue !== null ? badgeValue.label || badgeValue.text || badgeValue.status || "" : String(badgeValue ?? "");
    badgeElement.textContent = badgeText;
    badgeElement.style.display = badgeText ? "inline-flex" : "none";

    // Optional badge colors based on its text
    const status = badgeText.toLowerCase();
    if (status.includes("compliant") || status.includes("approved") || status.includes("pass")) {
      badgeElement.style.backgroundColor = "#e8f5e9";
      badgeElement.style.color = "#2e7d32";
      badgeElement.style.borderColor = "#c8e6c9";
    } else if (status.includes("non-compliant") || status.includes("rejected") || status.includes("fail")) {
      badgeElement.style.backgroundColor = "#ffebee";
      badgeElement.style.color = "#c62828";
      badgeElement.style.borderColor = "#ffcdd2";
    } else {
      badgeElement.style.backgroundColor = "#f5f5f5";
      badgeElement.style.color = "#616161";
      badgeElement.style.borderColor = "#e0e0e0";
    }
  }

  // Render sortable headings
  const header = table.querySelector("thead");
  if (header) {
    header.innerHTML = `
      <tr>
        ${columns.map(col => {
      const arrow = sortColumn === col.key ? sortDirection === "asc" ? " ▲" : " ▼" : " ↕";
      return `
            <th>
              <button
                type="button"
                class="sort-button"
                data-sort-key="${col.key}"
                aria-label="Sort by ${col.label}"
              >${col.label}${arrow}</button>
            </th>`;
    }).join("")}
      </tr>`;
  }

  // Sort selected column
  if (sortColumn) {
    const col = columns.find(c => c.key === sortColumn);
    rows.sort((a, b) => {
      let first = a[sortColumn];
      let second = b[sortColumn];
      if (col && col.numeric) {
        first = Number(first) || 0;
        second = Number(second) || 0;
        return sortDirection === "asc" ? first - second : second - first;
      }
      const result = String(first ?? "").localeCompare(String(second ?? ""), undefined, {
        numeric: true,
        sensitivity: "base"
      });
      return sortDirection === "asc" ? result : -result;
    });
  }

  // Render table rows
  if (!rows.length) {
    tbody.innerHTML = `
      <tr>
        <td colspan="5" class="empty-message">
          No compliance data available.
        </td>
      </tr>`;
    return;
  }
  tbody.innerHTML = rows.map(row => `
    <tr>
      <td>${escapeHTML(row.categoryName)}</td>
      <td class="rating">${escapeHTML(row.rating)}%</td>
      <td
        class="documents-cell"
        tabindex="0"
        role="link"
        data-document-url="${escapeHTML(row.documentsFoundUrl || "")}"
        aria-label="Open ${escapeHTML(row.documentsFound)}"
      >${escapeHTML(row.documentsFound)}</td>
      <td>${escapeHTML(row.documentsMissing)}</td>
      <td class="tq-status">${escapeHTML(row.tqQueryStatus)}</td>
    </tr>
  `).join("");
}

// Sorting: event delegation
document.getElementById("compliance-table").addEventListener("click", event => {
  const button = event.target.closest("[data-sort-key]");
  if (!button) return;
  const key = button.dataset.sortKey;
  if (sortColumn === key) {
    sortDirection = sortDirection === "asc" ? "desc" : "asc";
  } else {
    sortColumn = key;
    sortDirection = "asc";
  }
  renderComplianceTable();
});

// Open document when clicked
document.getElementById("compliance-body").addEventListener("click", event => {
  const cell = event.target.closest(".documents-cell");
  if (!cell) return;
  const url = cell.dataset.documentUrl;
  if (url) {
    window.open(url, "_blank", "noopener,noreferrer");
  }
});

// Keyboard support for document links
document.getElementById("compliance-body").addEventListener("keydown", event => {
  const cell = event.target.closest(".documents-cell");
  if (cell && (event.key === "Enter" || event.key === " ")) {
    event.preventDefault();
    const url = cell.dataset.documentUrl;
    if (url) {
      window.open(url, "_blank", "noopener,noreferrer");
    }
  }
});

// Initialize and refresh when the model changes
appsmith.onReady(() => {
  renderComplianceTable();
  appsmith.onModelChange(() => {
    renderComplianceTable();
  });
});

